// SPDX-License-Identifier: BSD-2-Clause-Patent
// A540 C3 bring-up: GPU-visible memory, SMMUv2 mapping, CP ring/microcode and
// the GPMU firmware load. This is deliberately a single self-contained module:
// the display bring-up calls it only after C1/C2 has powered GX and started the
// 257 MHz gfx3d clock (sheng-gpu-power=7).
//
// The firmware blobs are generated by scripts/gen-a540-firmware.py from the
// local vendor cache; they are never committed.

#include <stdint.h>
#include <string.h>
#include <IOKit/IOBufferMemoryDescriptor.h>
#include <IOKit/IODeviceMemory.h>
#include <IOKit/IOLib.h>
#include <kern/thread.h>

extern "C" {
#include "ArmSmmu4K.h"
#include "ArmSmmu4KContext.h"
#include "ArmSmmu4KProgram.h"
#include "ArmSmmu4KStreams.h"
#include "ArmSmmu4KMmio.h"
}

#include "A540FirmwareBlobs.h"

namespace {

constexpr uint64_t kGpuBase = 0x5000000ULL;
constexpr uint64_t kGpuBytes = 0x40000ULL;
constexpr uint64_t kSmmuBase = 0x5040000ULL;
constexpr uint64_t kSmmuBytes = 0x10000ULL;

// A540 register offsets are a5xx_reg.h dword indices; the MMIO helpers use bytes.
constexpr uint32_t CP_RB_BASE        = 0x800 * 4;
constexpr uint32_t CP_RB_BASE_HI     = 0x801 * 4;
constexpr uint32_t CP_RB_CNTL        = 0x802 * 4;
constexpr uint32_t CP_RB_RPTR_ADDR_LO= 0x804 * 4;
constexpr uint32_t CP_RB_RPTR_ADDR_HI= 0x805 * 4;
constexpr uint32_t CP_RB_RPTR        = 0x806 * 4;
constexpr uint32_t CP_RB_WPTR        = 0x807 * 4;
constexpr uint32_t CP_ME_CNTL        = 0x832 * 4;
constexpr uint32_t CP_PFP_INSTR_LO   = 0x835 * 4;
constexpr uint32_t CP_PFP_INSTR_HI   = 0x836 * 4;
constexpr uint32_t CP_PM4_INSTR_LO   = 0x838 * 4;
constexpr uint32_t CP_PM4_INSTR_HI   = 0x839 * 4;
constexpr uint32_t GPMU_CM3_SYSRESET = 0xa8d8 * 4;
constexpr uint32_t GPMU_GENERAL_0    = 0xa8e0 * 4;
constexpr uint32_t GPMU_GENERAL_1    = 0xa8e1 * 4;
constexpr uint32_t GPMU_INST_RAM     = 0x8800;

constexpr uint64_t kRingIova = 0x1000000ULL;
constexpr uint64_t kPm4Iova  = 0x1100000ULL;
constexpr uint64_t kPfpIova  = 0x1200000ULL;
constexpr uint64_t kGpmuIova = 0x1300000ULL;
constexpr uint64_t kRptrIova = 0x1400000ULL;
constexpr size_t kRingBytes  = 0x8000;   /* 32 KiB = 8192 dwords */
constexpr size_t kRptrBytes  = 0x1000;

struct GpuWindow {
    IOMemoryMap *map;
    volatile uint32_t *base;
};

struct Alloc {
    IOBufferMemoryDescriptor *desc;
    void *cpu;
    uint64_t phys;
    size_t bytes;

    bool init(size_t size) {
        unsigned options = (unsigned)kIODirectionInOut | (unsigned)kIOMemoryMapperNone |
                           (unsigned)kIOMemoryPhysicallyContiguous;
        desc = IOBufferMemoryDescriptor::inTaskWithPhysicalMask(
            kernel_task, (IOOptionBits)options,
            size, 0x0000000ffffff000ULL);
        if (!desc || desc->prepare() != kIOReturnSuccess)
            return false;
        cpu = desc->getBytesNoCopy();
        IOByteCount length = 0;
        phys = desc->getPhysicalSegment(0, &length, kIOMemoryMapperNone);
        bytes = size;
        if (!cpu || (phys & 0xfff) || length < size || (phys + size) > 0x10000000000ULL)
            return false;
        memset(cpu, 0, size);
        return true;
    }
    ~Alloc() {
        if (desc) {
            desc->complete();
            OSSafeReleaseNULL(desc);
        }
    }
};

static GpuWindow gGpu;
static GpuWindow gSmmu;

static bool mapWindow(uint64_t base, uint64_t bytes, GpuWindow *w) {
    IODeviceMemory *mem = IODeviceMemory::withRange(base, bytes);
    IOMemoryMap *map = mem ? mem->map(kIOMapAnywhere | kIOMapInhibitCache) : nullptr;
    OSSafeReleaseNULL(mem);
    if (!map)
        return false;
    volatile uint32_t *p = reinterpret_cast<volatile uint32_t *>(map->getVirtualAddress());
    if (!p) {
        OSSafeReleaseNULL(map);
        return false;
    }
    w->map = map;
    w->base = p;
    return true;
}

static uint32_t rd(uint32_t off) { return gGpu.base ? gGpu.base[off / 4] : 0xffffffffu; }
static void wr(uint32_t off, uint32_t v) {
    if (gGpu.base) {
        gGpu.base[off / 4] = v;
        __asm__ volatile("dmb oshst" ::: "memory");
    }
}

static void cleanDcache(void *p, size_t bytes) {
    uintptr_t a = reinterpret_cast<uintptr_t>(p) & ~UINT64_C(63);
    uintptr_t e = (reinterpret_cast<uintptr_t>(p) + bytes + 63) & ~UINT64_C(63);
    for (; a < e; a += 64)
        __asm__ volatile("dc cvac, %0" : : "r"(a) : "memory");
    __asm__ volatile("dsb sy" ::: "memory");
}

static void invalidateDcache(void *p, size_t bytes) {
    uintptr_t a = reinterpret_cast<uintptr_t>(p) & ~UINT64_C(63);
    uintptr_t e = (reinterpret_cast<uintptr_t>(p) + bytes + 63) & ~UINT64_C(63);
    for (; a < e; a += 64)
        __asm__ volatile("dc ivac, %0" : : "r"(a) : "memory");
    __asm__ volatile("dsb sy" ::: "memory");
}

static uint32_t type4(uint32_t addr, uint32_t count) {
    return 0x40000000u | ((count - 1) << 16) | (addr & 0xffffu);
}
static uint32_t type7(uint32_t opcode, uint32_t count) {
    return 0x70000000u | (opcode << 16) | (count - 1);
}

struct Ctx {
    void (*record)(uint32_t);
    Alloc tables, ring, pm4, pfp, gpmu, rptr;
    ArmSmmu4KMmio smmu_mmio;
    ArmSmmu4KIo io;
    ArmSmmu4KConfig cfg;
    ArmSmmu4KResult tables_result;
    ArmSmmu4KContextConfig ccfg;
    ArmSmmu4KProgramResult prog;
    ArmSmmu4KStreamState stream_state;
    ArmSmmu4KStreamResult stream_result;
    unsigned step;

    void put(uint32_t v) { if (record) record(v); }
    bool fail(unsigned code, const char *what) {
        put(0xdea00000u | code);
        IOLog("NATIVE_GPU_C3: fail step %u (%s)\n", code, what);
        return false;
    }
};

// The sheng ArmSmmu4K kit encodes an ARM MMU-500 context and refuses when
// ID0 bit30 / ID2 bit12 are clear. The msm8998 qcom,smmu-v2 uses the vendor
// arm-smmu.c layout (GR1 = base + 0x1000, CB0 = base + 0x8000 = reg_size/2,
// SMR/S2CR at 0x800/0xc00). Program the same stage-1 image directly when the
// kit reports Unsupported.
//
// H236u: the device tree marks the GPU SMMU qcom,skip-init + qcom,dynamic, so
// the bootloader may already own CB0 and the stream mapping. Writing CBA2R or
// CBAR while that bank is enabled is architecturally unpredictable and is the
// best explanation for H236t's ~70 s heartbeat block. Read the bank first and
// refuse instead of touching a live context.
static bool smmu_direct(Ctx &c) {
    const uint64_t root = c.tables_result.root_physical;
    const size_t CB = 0x8000, CBAR = 0x1000, CBA2R = 0x1800, SMR = 0x800, S2CR = 0xc00;
    uint32_t tcr = (2u << 30) | 0x3500u | (64u - 32u) | (1u << 23); /* T0SZ, EPD1 */
    uint32_t tcr2 = (7u << 15) | (1u << 4) | 2u;                    /* OAS 40 */
    uint64_t ttbr0 = (UINT64_C(1) << 48) | root;                    /* ASID 1 */
    uint64_t ttbr1 = (UINT64_C(1) << 48);
    uint32_t sctlr = 0x1067u | (1u << 8);                           /* CFCFG */

    uint32_t live_sctlr = 0, live_fsr = 0, live_s2cr = 0, live_smr = 0;
    if (c.io.read32(c.io.cookie, CB, &live_sctlr) ||
        c.io.read32(c.io.cookie, CB + 0x58, &live_fsr) ||
        c.io.read32(c.io.cookie, CBA2R, &live_s2cr) ||
        c.io.read32(c.io.cookie, SMR, &live_smr))
        return c.fail(7, "direct smmu read");
    if (live_sctlr & 1) {
        c.put(live_sctlr);
        c.put(live_fsr);
        c.put(live_s2cr);
        c.put(live_smr);
        IOLog("NATIVE_GPU_C3: cb0 already enabled sctlr=%08x fsr=%08x cba2r=%08x smr=%08x\n",
              live_sctlr, live_fsr, live_s2cr, live_smr);
        return c.fail(9, "cb0 enabled");
    }

    if (c.io.write32(c.io.cookie, CBA2R, 1) ||
        c.io.write32(c.io.cookie, CBAR, 0x1f300u) ||
        c.io.write32(c.io.cookie, CB + 0x10, tcr2) ||
        c.io.write32(c.io.cookie, CB + 0x30, tcr) ||
        c.io.write64(c.io.cookie, CB + 0x20, ttbr0) ||
        c.io.write64(c.io.cookie, CB + 0x28, ttbr1) ||
        c.io.write32(c.io.cookie, CB + 0x38, 0xff44u) ||
        c.io.write32(c.io.cookie, CB + 0x3c, 0) ||
        c.io.write32(c.io.cookie, CB + 0x58, 0xffffffffu))
        return c.fail(7, "direct smmu regs");

    c.io.barrier(c.io.cookie);
    c.io.write32(c.io.cookie, CB + 0x618, 0);          /* TLBIALL */
    c.io.write32(c.io.cookie, CB + 0x7f0, 0xffffffffu);/* TLBSYNC */
    for (unsigned i = 0; i < 2000; ++i) {
        uint32_t st = 1;
        if (c.io.read32(c.io.cookie, CB + 0x7f4, &st) || !(st & 1))
            break;
        for (unsigned d = 0; d < 64; ++d) __asm__ volatile("yield");
    }
    c.io.barrier(c.io.cookie);
    c.io.write32(c.io.cookie, CB, sctlr);
    c.io.barrier(c.io.cookie);

    uint32_t rback = 0, fsr = 0;
    c.io.read32(c.io.cookie, CB, &rback);
    c.io.read32(c.io.cookie, CB + 0x58, &fsr);
    c.put(rback);
    c.put(fsr);

    /* SID 0 -> CB0, stage-1 translation. */
    c.io.write32(c.io.cookie, S2CR, 0);
    c.io.write32(c.io.cookie, SMR, 0x80000000u);
    c.io.barrier(c.io.cookie);
    uint32_t smr = 0, s2cr = 0xffffffffu;
    c.io.read32(c.io.cookie, SMR, &smr);
    c.io.read32(c.io.cookie, S2CR, &s2cr);
    c.put(smr);
    c.put(s2cr);
    IOLog("NATIVE_GPU_C3: direct smmu cb=%08x fsr=%08x smr=%08x s2cr=%08x\n",
          rback, fsr, smr, s2cr);
    if (!(rback & 1) || (fsr & 0xc00001feu))
        return c.fail(8, "direct smmu enable");
    return true;
}

static bool smmu_setup(Ctx &c) {
    if (!mapWindow(kSmmuBase, kSmmuBytes, &gSmmu))
        return c.fail(1, "smmu map");
    c.smmu_mmio.mapping = reinterpret_cast<volatile unsigned char *>(gSmmu.base);
    c.smmu_mmio.bytes = kSmmuBytes;
    if (ArmSmmu4KBindMmio(&c.smmu_mmio, &c.io) != ArmSmmu4KSuccess)
        return c.fail(2, "smmu bind");

    uint32_t id0 = 0, id1 = 0, id2 = 0;
    if (c.io.read32(c.io.cookie, 0x20, &id0) || c.io.read32(c.io.cookie, 0x24, &id1) ||
        c.io.read32(c.io.cookie, 0x28, &id2))
        return c.fail(3, "smmu ids");
    c.put(id0); c.put(id1); c.put(id2);

    c.cfg.input_bits = 32;
    // H236x survey: ID2=0x00007511 gives IAS=36, OAS=36. The kit refuses an
    // output_bits above the hardware OAS, and the tables are 4K.
    c.cfg.output_bits = 36;
    c.cfg.table_physical = c.tables.phys;
    c.cfg.leaf_budget = 0x80000000ULL / 4096;

    ArmSmmu4KRange r[5] = {
        { kRingIova, c.ring.phys, kRingBytes, ArmSmmu4KRead | ArmSmmu4KWrite, 0, 3 },
        { kPm4Iova, c.pm4.phys, (c.pm4.bytes + 0xfff) & ~UINT64_C(0xfff), ArmSmmu4KRead, 0, 3 },
        { kPfpIova, c.pfp.phys, (c.pfp.bytes + 0xfff) & ~UINT64_C(0xfff), ArmSmmu4KRead, 0, 3 },
        { kGpmuIova, c.gpmu.phys, (c.gpmu.bytes + 0xfff) & ~UINT64_C(0xfff), ArmSmmu4KRead, 0, 3 },
        { kRptrIova, c.rptr.phys, kRptrBytes, ArmSmmu4KRead | ArmSmmu4KWrite, 0, 3 },
    };
    if (ArmSmmu4KBuild(&c.cfg, r, 5, reinterpret_cast<uint64_t *>(c.tables.cpu),
                       c.tables.bytes / 4096, &c.tables_result) != ArmSmmu4KSuccess)
        return c.fail(4, "smmu build");
    cleanDcache(c.tables.cpu, c.tables.bytes);

    memset(&c.ccfg, 0, sizeof(c.ccfg));
    c.ccfg.lower = &c.cfg;
    c.ccfg.lower_tables = &c.tables_result;
    c.ccfg.id0 = id0;
    c.ccfg.id2 = id2;
    c.ccfg.asid = 1;
    c.ccfg.coherent_walk = 1;
    c.ccfg.continue_after_fault = 1;

    ArmSmmu4KStatus st = ArmSmmu4KProgramDisabledContext(&c.io, 0, &c.ccfg, 1000, &c.prog);
    if (st != ArmSmmu4KSuccess) {
        uint32_t scr0 = 0;
        c.io.read32(c.io.cookie, 0x0, &scr0);
        c.put(0x70000000u | ((uint32_t)st & 0xffu));
        c.put(c.prog.phase);
        c.put(c.prog.fault_status);
        c.put(scr0);
        IOLog("NATIVE_GPU_C3: smmu context status=%u phase=%u fault=%08x scr0=%08x\n",
              (unsigned)st, c.prog.phase, c.prog.fault_status, scr0);
        if (st == ArmSmmu4KUnsupported)
            return smmu_direct(c);
        return c.fail(5, "smmu context");
    }
    c.put(c.prog.readback.sctlr);
    c.put(c.prog.readback.ttbr0 >> 32);

    // arm-smmu.c writes ACTLR=0x70000000 for SMMU_MODEL_QCOM_V2 (OSH/ISH/NSH);
    // the kit's image does not include ACTLR.
    if (c.io.write32(c.io.cookie, 0x8004, 0x70000000u) || c.io.barrier(c.io.cookie))
        return c.fail(6, "smmu actlr");
    // H236z: S2CR reads 0x000200ff for FAULT (cbndx reads as 0xff), so the
    // kit's "target slot must be exactly FAULT" preflight returns Busy. The
    // firmware leaves SMR invalid, so publish the SID0->CB0 route here:
    // S2CR first (translation, CB0), then SMR0 (VALID | SID 0).
    if (c.io.write32(c.io.cookie, 0xc00, 0) || c.io.barrier(c.io.cookie) ||
        c.io.write32(c.io.cookie, 0x800, 0x80000000u) || c.io.barrier(c.io.cookie))
        return c.fail(6, "smmu route write");
    uint32_t route_s2cr = ~0u, route_smr = 0;
    c.io.read32(c.io.cookie, 0xc00, &route_s2cr);
    c.io.read32(c.io.cookie, 0x800, &route_smr);
    c.put(route_s2cr);
    c.put(route_smr);
    if (route_s2cr != 0 || route_smr != 0x80000000u)
        return c.fail(6, "smmu route readback");
    return true;
}

static bool cp_init(Ctx &c) {
    if (!mapWindow(kGpuBase, kGpuBytes, &gGpu))
        return c.fail(10, "gpu map");

    memcpy(c.pm4.cpu, a540_fw_pm4 + 4, a540_fw_pm4_size - 4);
    memcpy(c.pfp.cpu, a540_fw_pfp + 4, a540_fw_pfp_size - 4);
    cleanDcache(c.pm4.cpu, c.pm4.bytes);
    cleanDcache(c.pfp.cpu, c.pfp.bytes);

    c.put(rd(0x13d4));            /* RBBM_STATUS before the CP writes */

    /* H236ag: the bootloader leaves the CP in an unknown (possibly halted)
     * state, so writing INSTR_BASE + ME_CNTL=0 may never reload the
     * microcode. Pulse the GPU block reset (RBBM excluded, same value the
     * vendor uses when RBBM itself cannot be reset) and re-init afterwards.
     * The SMMU lives outside these blocks and keeps its context. */
    wr(0x45 * 4, 0xffdffc0u);
    wr(0x46 * 4, 0x1fffffffu);
    __asm__ volatile("dsb sy" ::: "memory");
    for (unsigned i = 0; i < 20000; ++i) __asm__ volatile("yield");
    wr(0x45 * 4, 0);
    wr(0x46 * 4, 0);
    __asm__ volatile("dsb sy" ::: "memory");
    for (unsigned i = 0; i < 20000; ++i) __asm__ volatile("yield");
    c.put(rd(0x13d4));

    /* H236af: a5xx_start() starts VBIF before the CP. Without it the CP's
     * memory fetch can hang and RBBM stays busy. a540_vbif = two writes. */
    wr(0xc124, 0x00000003u);     /* A5XX_VBIF_ROUND_ROBIN_QOS_ARB */
    wr(0xc0a8, 0x00000009u);     /* A5XX_VBIF_GATE_OFF_WRREQ_EN */

    /* H236ad: a5xx_start() programs the CP queue thresholds before the ring;
     * zero-sized ME queues keep the ME from consuming ME_INIT. */
    wr(0x2094, 0x40);            /* CP_MEQ_THRESHOLDS (A540) */
    wr(0x2098, 0x400);           /* CP_MERCIU_SIZE */
    wr(0x2080, 0x80000060u);     /* CP_ROQ_THRESHOLDS_2 */
    wr(0x207c, 0x40201b16u);     /* CP_ROQ_THRESHOLDS_1 */

    wr(CP_RB_RPTR_ADDR_LO, (uint32_t)kRptrIova);
    wr(CP_RB_RPTR_ADDR_HI, (uint32_t)(kRptrIova >> 32));
    wr(CP_RB_CNTL, (2u << 8) | 12u);            /* 32 KiB ring, 4-byte? */
    wr(CP_RB_BASE, (uint32_t)kRingIova);
    wr(CP_RB_BASE_HI, (uint32_t)(kRingIova >> 32));
    wr(CP_PM4_INSTR_LO, (uint32_t)kPm4Iova);
    wr(CP_PM4_INSTR_HI, (uint32_t)(kPm4Iova >> 32));
    wr(CP_PFP_INSTR_LO, (uint32_t)kPfpIova);
    wr(CP_PFP_INSTR_HI, (uint32_t)(kPfpIova >> 32));
    wr(CP_ME_CNTL, 0);
    __asm__ volatile("dsb sy" ::: "memory");

    uint32_t *ring = reinterpret_cast<uint32_t *>(c.ring.cpu);
    memset(ring, 0, kRingBytes);
    unsigned n = 0;
    ring[n++] = type7(0x48 /*CP_ME_INIT*/, 8);
    ring[n++] = 0x2f;            /* CP_INIT_MASK */
    ring[n++] = 3;               /* multiple hardware contexts */
    ring[n++] = 0x20000000;      /* error detection */
    ring[n++] = 0;               /* header dump addr */
    ring[n++] = 0;               /* header dump enable/size */
    ring[n++] = 0x0a;            /* A540v1 ucode workarounds (adreno_a5xx.c) */
    ring[n++] = 0;
    ring[n++] = 0;
    cleanDcache(ring, n * 4);
    wr(CP_RB_WPTR, n);

    for (unsigned i = 0; i < 20000; ++i) {
        if (rd(CP_RB_RPTR) == n)
            break;
        for (unsigned d = 0; d < 64; ++d) __asm__ volatile("yield");
    }
    c.put(rd(CP_RB_RPTR));
    c.put(rd(0x13d4));            /* RBBM_STATUS */
    c.put(rd(CP_ME_CNTL));
    c.put(rd(CP_RB_WPTR));
    c.put(rd(CP_PFP_INSTR_LO));
    invalidateDcache(c.rptr.cpu, 64);
    c.put(reinterpret_cast<volatile uint32_t *>(c.rptr.cpu)[0]);  /* RPTR shadow */
    c.put(rd(0x48));              /* sGFSR (unmatched/SID faults) */
    c.put(rd(0x8058));            /* CB0 FSR */
    c.put(rd(0x8060));            /* CB0 FAR_LO */
    IOLog("NATIVE_GPU_C3: cp rptr=%08x rbbm=%08x me=%08x wptr=%08x shadow=%08x "
          "gfsr=%08x fsr=%08x far=%08x\n",
          rd(CP_RB_RPTR), rd(0x13d4), rd(CP_ME_CNTL), rd(CP_RB_WPTR),
          reinterpret_cast<volatile uint32_t *>(c.rptr.cpu)[0],
          rd(0x48), rd(0x8058), rd(0x8060));
    if (rd(CP_RB_RPTR) != n)
        return c.fail(11, "cp me init");
    return true;
}

static bool gpmu_load(Ctx &c) {
    const uint32_t *fw = reinterpret_cast<const uint32_t *>(a540_fw_gpmu);
    uint32_t total = fw[0];
    uint32_t id = fw[1];
    uint32_t hdr = fw[2];
    if (id != 2 || total < 16 || hdr == 0 || hdr >= total ||
        (total - hdr - 2) > 0xfff)
        return c.fail(20, "gpmu header");
    const uint32_t *code = fw + hdr + 3;
    uint32_t code_dwords = total - hdr - 2;

    uint32_t *ring = reinterpret_cast<uint32_t *>(c.ring.cpu);
    unsigned n = rd(CP_RB_RPTR);
    unsigned start = n;
    ring[n++] = type7(0x5f /*CP_SET_PROTECTED_MODE*/, 1);
    ring[n++] = 0;
    for (uint32_t at = 0; at < code_dwords; ) {
        uint32_t chunk = code_dwords - at;
        if (chunk > 15)
            chunk = 15;
        ring[n++] = type4(GPMU_INST_RAM + at, chunk);
        for (uint32_t i = 0; i < chunk; ++i)
            ring[n++] = code[at + i];
        at += chunk;
    }
    ring[n++] = type7(0x5f /*CP_SET_PROTECTED_MODE*/, 1);
    ring[n++] = 1;
    cleanDcache(ring + start, (n - start) * 4);
    wr(CP_RB_WPTR, n);

    for (unsigned i = 0; i < 4000; ++i) {
        if (rd(CP_RB_RPTR) == n)
            break;
        for (unsigned d = 0; d < 64; ++d) __asm__ volatile("yield");
    }
    c.put(rd(CP_RB_RPTR));
    if (rd(CP_RB_RPTR) != n)
        return c.fail(21, "gpmu packets");

    wr(GPMU_CM3_SYSRESET, 0);
    uint32_t general = 0;
    for (unsigned i = 0; i < 20000; ++i) {
        general = rd(GPMU_GENERAL_0);
        if (general == 0xBABEFACEu)
            break;
        for (unsigned d = 0; d < 128; ++d) __asm__ volatile("yield");
    }
    c.put(general);
    c.put(rd(GPMU_GENERAL_1));
    if (general != 0xBABEFACEu)
        return c.fail(22, "gpmu handshake");
    return true;
}

} // namespace

static Ctx *gC3;
static volatile int gC3Started, gC3Done;

static void c3_thread(void *, wait_result_t) {
    Ctx *c = gC3;
    IOLog("NATIVE_GPU_C3: thread start\n");
    if (!c) {
        gC3Done = 1;
        return;
    }
    IOLog("NATIVE_GPU_C3: alloc tables\n");
    if (!c->tables.init(0x40000)) { c->put(0xdea00031u); gC3Done = 1; return; }
    IOLog("NATIVE_GPU_C3: alloc ring\n");
    if (!c->ring.init(kRingBytes)) { c->put(0xdea00032u); gC3Done = 1; return; }
    if (!c->pm4.init((a540_fw_pm4_size + 0xfff) & ~0xfffu)) { c->put(0xdea00033u); gC3Done = 1; return; }
    if (!c->pfp.init((a540_fw_pfp_size + 0xfff) & ~0xfffu)) { c->put(0xdea00034u); gC3Done = 1; return; }
    if (!c->gpmu.init((a540_fw_gpmu_size + 0xfff) & ~0xfffu)) { c->put(0xdea00035u); gC3Done = 1; return; }
    if (!c->rptr.init(kRptrBytes)) { c->put(0xdea00036u); gC3Done = 1; return; }
    c->put((uint32_t)(c->tables.phys >> 12));
    c->put((uint32_t)(c->ring.phys >> 12));

    IOLog("NATIVE_GPU_C3: smmu setup\n");
    if (!smmu_setup(*c)) { gC3Done = 1; return; }
    IOLog("NATIVE_GPU_C3: cp init\n");
    if (!cp_init(*c)) { gC3Done = 1; return; }
    IOLog("NATIVE_GPU_C3: gpmu load\n");
    if (!gpmu_load(*c)) { gC3Done = 1; return; }

    IOLog("NATIVE_GPU_C3: GPMU firmware reached BABEFACE\n");
    c->put(0x600d00c3u);
    gC3Done = 1;
}

extern "C" int sheng_a540_c3_run(void (*record)(uint32_t)) {
    if (gC3Started)
        return -1;
    gC3 = new Ctx();
    if (!gC3)
        return -2;
    gC3->record = record;
    gC3Started = 1;
    /* Run synchronously: the threaded version did not reach its first log on
     * H236s (kernel thread start instability). The synchronous path already
     * reached the SMMU on H236p. */
    c3_thread(nullptr, 0);
    return 0;
}
